-- Google Drive photo albums for inventory pieces (legacy compatibility,
-- Nov 2026).
--
-- On the CEPCo Inventory Log Google Sheet, each piece's name in column A is
-- a hyperlink to that piece's photo folder in Google Drive. The CSV export
-- the inventory import ran from (scripts/importInventory.js, migration 072)
-- keeps a cell's text and silently drops its hyperlink, so none of those
-- links made it into MC2. This adds a place for them and fills it from an
-- .xlsx export of the same sheet (which does keep hyperlinks).
--
-- 1. photo_album_url on instruments and on inventory_parts (18 of the
--    linked rows are Parts & Accessories, e.g. spare cases). Editable on the
--    inventory pages, so new pieces can get one too. Alongside MC2's own
--    photo sets, not instead of them -- the Drive folders stay where they
--    are; this is only a link to them.
--
-- 2. Backfill. Every imported row kept where it came from in import_raw
--    (sheet file + 1-based row number + the row's cells), and the .xlsx is
--    the same sheet the CSVs were exported from: all 287 links sit on the
--    exact row the import recorded, with the same name in column A. Both
--    are checked here (sheet+row to find the row, name to make sure it's
--    still the same piece), so a row that's somehow moved is left blank
--    rather than given someone else's album. Only empty fields are filled,
--    so a link someone already typed in by hand is never overwritten.
--
--    Only Drive *folder* links in the five instrument sheets are here. The
--    sheet's other hyperlinks are Xero contact links on consignor names
--    (Consignment Tracking, a few notes cells) -- consignors are linked to
--    customers, and so to Xero, separately.
--
--    Generated from "CEPCo Inventory Log.xlsx" (exported Nov 5 2026):
--    287 rows -- 109 Rhodes, 77 Wurlitzer, 30 Hohner, 65 Combo Organs / String Pianos, 6 Other.

ALTER TABLE instruments     ADD COLUMN IF NOT EXISTS photo_album_url TEXT;
ALTER TABLE inventory_parts ADD COLUMN IF NOT EXISTS photo_album_url TEXT;

CREATE TEMP TABLE legacy_photo_albums (sheet TEXT, sheet_row INT, name TEXT, url TEXT) ON COMMIT DROP;

UPDATE instruments i
   SET photo_album_url = a.url
  FROM legacy_photo_albums a
 WHERE i.import_raw->>'sheet' = a.sheet
   AND (i.import_raw->>'row')::int = a.sheet_row
   AND trim(i.import_raw->'cells'->>0) = trim(a.name)
   AND i.photo_album_url IS NULL;

UPDATE inventory_parts p
   SET photo_album_url = a.url
  FROM legacy_photo_albums a
 WHERE p.import_raw->>'sheet' = a.sheet
   AND (p.import_raw->>'row')::int = a.sheet_row
   AND trim(p.import_raw->'cells'->>0) = trim(a.name)
   AND p.photo_album_url IS NULL;
